command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/current-main-packaging-20261005"
$candidate="a84ff56597ca638b31fdcb4a5b0bc1356cb443f3"
$temp=Join-Path $env:RUNNER_TEMP ("current-main-packaging-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $observedMain=(& git rev-parse refs/remotes/origin/main).Trim()
  $observedBranch=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($observedMain -ne $candidate){throw "main moved before packaging: $observedMain"}
  if($observedBranch -ne $candidate){throw "work branch moved before packaging: $observedBranch"}

  if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  & python -X utf8 tools\winui\check_python_static.py packaging\provenance.py packaging\package.py tools\winui\diagnose_installed_shutdown.py tests\winui\test_installed_lifecycle.py tests\winui\test_installer_contract.py tests\winui\test_release_payload_contract.py
  if($LASTEXITCODE -ne 0){throw "packaging static check failed"}
  & python -X utf8 -m unittest tests.winui.test_release_payload_contract tests.winui.test_installer_contract
  if($LASTEXITCODE -ne 0){throw "packaging contract tests failed"}

  & .\clean.bat build
  if($LASTEXITCODE -ne 0){throw "clean build output failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 packaging\provenance.py --write
  if($LASTEXITCODE -ne 0){throw "payload provenance generation failed"}
  & python -X utf8 packaging\provenance.py --check
  if($LASTEXITCODE -ne 0){throw "payload provenance verification failed"}

  & .\package.bat Release
  if($LASTEXITCODE -ne 0){throw "current Release package build failed"}

  & python -X utf8 tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "bounded installed lifecycle failed"}

  $provenance=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.json" | ConvertFrom-Json
  Write-Host ("CURRENT_PACKAGE_SOURCE_REVISION="+$provenance.runtime_source_revision)
  Write-Host ("CURRENT_PACKAGE_RUNTIME_FILES="+$provenance.runtime_file_count)
  Write-Host ("CURRENT_PACKAGE_PRODUCT_FILES="+$provenance.product_generated_file_count)
  Write-Host ("CURRENT_PACKAGE_NUGET_FILES="+$provenance.nuget_matched_file_count)
  Write-Host ("CURRENT_PACKAGE_MANIFEST_SHA256="+$provenance.runtime_manifest_sha256)

  $changed=@(& git diff --name-only)
  if($LASTEXITCODE -ne 0){throw "failed to inspect generated provenance diff"}
  $expected=@("packaging/licenses/PAYLOAD_PROVENANCE.json","packaging/licenses/PAYLOAD_PROVENANCE.md")
  $unexpected=@($changed | Where-Object { $_ -notin $expected })
  $missing=@($expected | Where-Object { $_ -notin $changed })
  if($unexpected.Count -gt 0 -or $missing.Count -gt 0){
    throw ("unexpected tracked changes after packaging; changed="+($changed -join ","))
  }
  & git diff --check
  if($LASTEXITCODE -ne 0){throw "generated provenance diff check failed"}

  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags
  if($LASTEXITCODE -ne 0){throw "pre-push fetch failed"}
  $latestMain=(& git rev-parse refs/remotes/origin/main).Trim()
  $latestBranch=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($latestMain -ne $candidate){throw "main moved during packaging: $latestMain"}
  if($latestBranch -ne $candidate){throw "work branch moved during packaging: $latestBranch"}

  Set-Location -LiteralPath $temp
  & git add -- packaging/licenses/PAYLOAD_PROVENANCE.json packaging/licenses/PAYLOAD_PROVENANCE.md
  if($LASTEXITCODE -ne 0){throw "failed to stage provenance"}
  & git -c user.name="flyExplorer automation" -c user.email="actions@flyexplorer.local" commit -m "build: refresh current Release payload provenance"
  if($LASTEXITCODE -ne 0){throw "failed to commit provenance"}
  $provenanceCommit=(& git rev-parse HEAD).Trim()
  & git push origin ("HEAD:refs/heads/"+$branch)
  if($LASTEXITCODE -ne 0){throw "failed to push provenance commit"}
  Write-Host ("CURRENT_PACKAGE_PROVENANCE_COMMIT="+$provenanceCommit)
  Write-Host "CURRENT_MAIN_PACKAGING_ACCEPTANCE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
